//github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/request_processor.cr#L6"},"def":{"name":"max_headers_size","visibility":"Public","body":"@max_headers_size"},"external_var":false},{"html_id":"max_headers_size=(max_headers_size)-instance-method","name":"max_headers_size=","abstract":false,"args":[{"name":"max_headers_size","external_name":"max_headers_size","restriction":""}],"args_string":"(max_headers_size)","args_html":"(max_headers_size)","location":{"filename":"src/orion/server/request_processor.cr","line_number":6,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/request_processor.cr#L6"},"def":{"name":"max_headers_size=","args":[{"name":"max_headers_size","external_name":"max_headers_size","restriction":""}],"visibility":"Public","body":"@max_headers_size = max_headers_size"},"external_var":false},{"html_id":"max_request_line_size:Int32-instance-method","name":"max_request_line_size","doc":"Maximum permitted size of the request line in an HTTP request.","summary":"<p>Maximum permitted size of the request line in an HTTP request.</p>","abstract":false,"location":{"filename":"src/orion/server/request_processor.cr","line_number":6,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/request_processor.cr#L6"},"def":{"name":"max_request_line_size","visibility":"Public","body":"@max_request_line_size"},"external_var":false},{"html_id":"max_request_line_size=(max_request_line_size)-instance-method","name":"max_request_line_size=","abstract":false,"args":[{"name":"max_request_line_size","external_name":"max_request_line_size","restriction":""}],"args_string":"(max_request_line_size)","args_html":"(max_request_line_size)","location":{"filename":"src/orion/server/request_processor.cr","line_number":6,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/request_processor.cr#L6"},"def":{"name":"max_request_line_size=","args":[{"name":"max_request_line_size","external_name":"max_request_line_size","restriction":""}],"visibility":"Public","body":"@max_request_line_size = max_request_line_size"},"external_var":false},{"html_id":"process(input:IO,output:IO):Nil-instance-method","name":"process","abstract":false,"args":[{"name":"input","external_name":"input","restriction":"IO"},{"name":"output","external_name":"output","restriction":"IO"}],"args_string":"(input : IO, output : IO) : Nil","args_html":"(input : IO, output : IO) : Nil","location":{"filename":"src/orion/server/request_processor.cr","line_number":6,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/request_processor.cr#L6"},"def":{"name":"process","args":[{"name":"input","external_name":"input","restriction":"IO"},{"name":"output","external_name":"output","restriction":"IO"}],"return_type":"Nil","visibility":"Public","body":"response = Response.new(output)\n\nbegin\n  while !@wants_close\n    request = ::Orion::Server::Request.from_io(input, max_request_line_size: max_request_line_size, max_headers_size: max_headers_size)\n\n\n    if request\n    else\n      break\n    end\n\n    response.reset\n\n    if request.is_a?(HTTP::Status)\n      response.respond_with_status(request)\n      return\n    end\n\n    response.version = request.version\n    if request.keep_alive?\n      response.headers[\"Connection\"] = \"keep-alive\"\n    end\n    context = Context.new(request, response)\n\n    Log.with_context do\n      begin\n        @handler.call(context)\n      rescue ex : ClientError\n        Log.debug(exception: ex.cause) do ex.message end\n      rescue ex\n        Log.error(exception: ex) do \"Unhandled exception on HTTP::Handler\" end\n        if response.closed?\n        elsif response.wrote_headers?\n        else\n          response.respond_with_status(:internal_server_error)\n        end\n        return\n      ensure\n        response.output.close\n      end\n    end\n\n    output.flush\n\n\n\n    if upgrade_handler = response.upgrade_handler\n      upgrade_handler.call(output)\n      return\n    end\n\n    if request.keep_alive?\n    else\n      break\n    end\n\n\n    if HTTP.keep_alive?(response)\n    else\n      break\n    end\n\n\n\n\n    case body = request.body\n    when FixedLengthContent\n      if body.read_remaining > 0\n        break\n      end\n    when ChunkedContent\n      if body.closed?\n      else\n        break\n      end\n    end\n  end\nrescue IO::Error\nend\n"},"external_var":false}]},{"html_id":"orion/Orion/Server/Response","path":"Orion/Server/Response.html","kind":"class","full_name":"Orion::Server::Response","name":"Response","abstract":false,"superclass":{"html_id":"orion/HTTP/Server/Response","kind":"class","full_name":"HTTP::Server::Response","name":"Response"},"ancestors":[{"html_id":"orion/HTTP/Server/Response","kind":"class","full_name":"HTTP::Server::Response","name":"Response"},{"html_id":"orion/IO","kind":"class","full_name":"IO","name":"IO"},{"html_id":"orion/Reference","kind":"class","full_name":"Reference","name":"Reference"},{"html_id":"orion/Object","kind":"class","full_name":"Object","name":"Object"}],"locations":[{"filename":"src/orion/server/response.cr","line_number":1,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/server/response.cr#L1"}],"repository_name":"orion","program":false,"enum":false,"alias":false,"const":false,"namespace":{"html_id":"orion/Orion/Server","kind":"class","full_name":"Orion::Server","name":"Server"}}]},{"html_id":"orion/Orion/View","path":"Orion/View.html","kind":"module","full_name":"Orion::View","name":"View","abstract":false,"locations":[{"filename":"src/orion/view.cr","line_number":3,"url":"https://github.com/obsidian/orion/blob/ec9c977967744ab70089c37bc3b735ca1a4d84af/src/orion/view.cr#L3"},{"filename":"src/orion/view/asset_tag_helpers.cr","line_number":8,"url":"https://